const requests = [
  {id:'austin',agent:'roam',type:'approval',title:'A place to land in Austin',preview:'Found a little breathing room by the river. Ready to book your stay?',project:'Austin trip',time:'2m',minutes:2,intro:'I found a stay that feels like you: good design, a little nature, and room to slow down. <strong>The LINE</strong> is right by the lake, a short walk from your meetings.',label:'Booking approval'},
  {id:'runs',agent:'codex',type:'choice',title:'A home for your agent runs',preview:'Two ways to structure the data. I have a recommendation, but it’s your call.',project:'Somae',time:'8m',minutes:8,intro:'I’m at a small fork in the architecture. We can extend the sessions table or give agent runs a home of their own. Here’s how I’d think about it.',label:'Architecture decision'},
  {id:'onboarding',agent:'claude',type:'review',title:'The first hello, ready for a look',preview:'The onboarding copy is ready. A few words to help people feel at home.',project:'Somae',time:'14m',minutes:14,intro:'I’ve drafted the first few moments in Somae. The goal is to help someone understand their space without making it feel like setup. Take a look when you have a moment.',label:'Copy review'},
  {id:'weekend',agent:'roam',type:'question',title:'What kind of weekend do you need?',preview:'Something slow, or a little adventure? I’ll take it from there.',project:'Personal',time:'32m',minutes:32,intro:'You have a free weekend coming up. Before I start finding places, what would feel good? A quiet cabin, a day outside, a new neighborhood—or something else entirely?',label:'A quick question'},
  {id:'research',agent:'research',type:'review',title:'A few things worth knowing',preview:'Your agent identity research is ready. Three patterns stood out.',project:'Somae',time:'1h',minutes:60,intro:'I’ve pulled together the identity and permission patterns from our working notes. There are three useful ideas here that could shape the first connection flow.',label:'Research review'}
];
let saved = {};
try { saved = JSON.parse(localStorage.getItem('somae-prototype') || '{}'); } catch { /* storage is optional */ }
const state = { selected:'austin',filter:'all',sort:'newest',mobileDetail:false,quiet:false,theme:'clay',choices:{},answers:{},snoozed:[],comments:{},connections:{codex:true,claude:true,roam:true,research:true},pending:{studio:true,brian:true},context:{},profile:{name:'Scott Moss',handle:'scott',bio:'Building Somae. Making a little room for the human.'},...saved };
let hotel = 'line';
let toastTimer;
let activePage = 'inbox';
function persist(){try {localStorage.setItem('somae-prototype',JSON.stringify(state));} catch {}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function pendingRequests(){return requests.filter(r=>!state.answers[r.id]&&!state.snoozed.includes(r.id));}
function nav(){const n=pendingRequests().length;$('#navigation').innerHTML=`<p class="nav-label">A LITTLE ROOM FOR YOU</p>${[['inbox','inbox','Needs you',n],['activity','activity','Activity',3],['requests','requests','Requests',Object.values(state.pending).filter(Boolean).length]].map(([id,i,label,count])=>`<a class="nav-link ${activePage===id?'active':''}" href="#${id}" ${activePage===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${count?`<span class="nav-count ${id==='activity'?'live':''}">${count}</span>`:''}</a>`).join('')}<p class="nav-label">YOUR WORLD</p>${[['context','context','Context'],['connections','connections','Connections']].map(([id,i,label])=>`<a class="nav-link ${activePage===id?'active':''}" href="#${id}" ${activePage===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}`;$('#appearance-link').innerHTML=icon('appearance')+'<span>Make it yours</span>';$('#appearance-link').setAttribute('aria-label','Appearance');}
function heading(title,subtitle,eyebrow='YOUR SPACE'){return `<section class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="heading-tools"><a class="working-pill" href="#activity"><span class="status-dot"></span>3 agents at work ${icon('arrow')}</a></div></section>`;}
function card(r){const answered=!!state.answers[r.id];return `<button class="request-card ${state.selected===r.id?'selected':''}" data-request="${r.id}" aria-pressed="${state.selected===r.id}"><span class="request-top">${avatar(r.agent)}<strong>${agents[r.agent].name}</strong><time>${r.time} ago</time></span><h3>${r.title}</h3><p>${r.preview}</p><span class="request-bottom"><span class="request-kind">${icon(answered?'check':r.type==='approval'?'check':r.type)}${answered?'Answered':r.type==='approval'?'Approval':r.type[0].toUpperCase()+r.type.slice(1)}</span><span class="project-tag">${r.project}</span></span></button>`;}
function inbox({keepSelected=false}={}){let filtered=state.filter==='answered'?requests.filter(r=>state.answers[r.id]):state.filter==='later'?requests.filter(r=>state.snoozed.includes(r.id)):pendingRequests().filter(r=>state.filter==='all'||r.type===state.filter);filtered.sort((a,b)=>state.sort==='oldest'?b.minutes-a.minutes:a.minutes-b.minutes);if(!keepSelected&&!filtered.some(r=>r.id===state.selected))state.selected=filtered[0]?.id || null;const r=requests.find(r=>r.id===state.selected);$('#main').innerHTML=heading('Needs you','A few things only you can move forward.')+`<div class="toolbar"><div class="filter-tabs" role="group" aria-label="Filter requests">${[['all','All requests'],['approval','Approvals'],['choice','Choices'],['question','Questions'],['review','Reviews']].map(([id,label])=>`<button class="filter-tab ${state.filter===id?'active':''}" data-filter="${id}" aria-pressed="${state.filter===id}">${label}${id==='all'?`<span>${pendingRequests().length}</span>`:''}</button>`).join('')}</div><select class="sort-select" id="sort" aria-label="Sort requests"><option value="newest" ${state.sort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${state.sort==='oldest'?'selected':''}>Oldest first</option></select></div><div class="inbox-workspace ${state.mobileDetail?'show-detail':''}"><section class="inbox-list" aria-label="Requests"><div class="list-caption"><span>${state.filter==='answered'?'ANSWERED':state.filter==='later'?'SAVED FOR LATER':'A MOMENT OF YOUR TIME'}</span><span>${filtered.length} ${filtered.length===1?'request':'requests'}</span></div>${filtered.length?filtered.map(card).join(''):`<div class="empty-state">${icon('leaf')}<h2>A little breathing room.</h2><p>No requests here right now.</p><button class="button secondary" data-filter="all">All requests</button></div>`}<div class="list-finish">No rush. They're waiting for you.</div><div class="filter-tabs" style="justify-content:center"><button class="filter-tab ${state.filter==='answered'?'active':''}" data-filter="answered">Answered ${Object.keys(state.answers).length}</button><button class="filter-tab ${state.filter==='later'?'active':''}" data-filter="later">Later ${state.snoozed.length}</button></div></section><article class="request-detail" id="request-detail" aria-label="Selected request">${r?detail(r):`<div class="empty-state">${icon('heart')}<h2>All caught up.</h2><p>Your agents can take it from here.</p><button class="button secondary" data-filter="answered">See your responses</button></div>`}</article></div>`;bindInbox();}
const hotels={line:{name:'The LINE Austin',total:'$1,486'},carpenter:{name:'Carpenter Hotel',total:'$1,248'},san:{name:'Hotel San José',total:'$1,362'}};
function requestContent(r){if(r.id==='austin')return `<div class="canvas-wrap"><div class="canvas-bar"><span class="canvas-label">${icon('globe')}Roam / Your Austin stay</span><button class="canvas-expand" id="expand-canvas">Open canvas ${icon('expand')}</button></div><iframe id="trip-canvas" title="Interactive Austin hotel comparison" sandbox="allow-scripts" src="/prototypes/desktop/canvases/trip.html?hotel=${hotel}&theme=${state.theme}"></iframe></div><p class="detail-intro" style="margin-bottom:0">Nothing is booked yet. Your approval gives me permission to reserve this stay.</p>`;
if(r.id==='runs')return `<div class="choice-list"><label class="choice-option"><input type="radio" name="architecture" value="Create agent_runs table" ${(!state.choices[r.id]||state.choices[r.id]==='Create agent_runs table')?'checked':''} ${state.answers[r.id]?'disabled':''}><div><strong>Create an agent_runs table <span class="recommended">Recommended</span></strong><p>Keep execution history separate from human conversations. More room for retries, events, and multiple runs per session.</p></div></label><label class="choice-option"><input type="radio" name="architecture" value="Extend existing sessions table" ${state.choices[r.id]==='Extend existing sessions table'?'checked':''} ${state.answers[r.id]?'disabled':''}><div><strong>Extend the sessions table</strong><p>A smaller change today. Add run state to the existing structure and split it out when we need to.</p></div></label></div><div class="code-preview">agent_runs\n  id · session_id · agent_id\n  status · started_at · completed_at</div><div class="note-block"><strong>What happens next</strong><br>I’ll draft the migration and update the API around your choice. No existing data will change yet.</div>`;
if(r.id==='onboarding')return `<div class="review-doc"><span class="eyebrow">FIRST-RUN EXPERIENCE / DRAFT 02</span><h3>A little room for you.</h3><p>Your agents can do a lot. Every now and then, they need something only you can give: a decision, a detail, a go-ahead.</p><p>This is where those moments come together. Connect your first agent, and let it meet you here.</p><p><em>You set the boundaries. They take it from there.</em></p></div><div class="artifact-card">${icon('file')}<div><h3>Onboarding copy</h3><p>3 screens · Draft 02 · Just updated</p></div><button class="button secondary" data-download="onboarding">Save draft ${icon('arrow')}</button></div>`;
if(r.id==='weekend')return `<div class="choice-list">${['A quiet cabin & a good book','A day outside','Somewhere new to wander'].map(text=>`<button class="choice-option suggestion" data-suggestion="${text}" ${state.answers[r.id]?'disabled':''}>${icon('leaf')}<strong>${text}</strong></button>`).join('')}</div><div class="note-block">A sentence is plenty. Tell me the feeling you’re after, and I’ll find a few ideas.</div>`;
return `<div class="review-doc"><span class="eyebrow">FIELD NOTES / AGENT IDENTITY</span><h3>Trust starts before the first message.</h3><p><strong>01 · A handle is an invitation to connect.</strong><br>Discovery and permission are separate moments. Knowing a person’s handle doesn’t create the right to interrupt them.</p><p><strong>02 · Make the scope understandable.</strong><br>“Ask you questions” is easier to review than an opaque list of API permissions. Show both, at different depths.</p><p><strong>03 · Give trust an expiration.</strong><br>Once, this session, or until revoked. The duration should be part of the decision, not buried in settings.</p></div><div class="artifact-card">${icon('file')}<div><h3>Agent identity — working notes</h3><p>3 findings · Internal research</p></div><button class="button secondary" data-download="research">Save notes ${icon('arrow')}</button></div>`;
}
function detail(r){const answer=state.answers[r.id];const snoozed=state.snoozed.includes(r.id);const comments=state.comments[r.id]||[];return `<header class="detail-head"><div class="sender"><button class="icon-button back-list" aria-label="Back to requests" id="back-list">${icon('back')}</button>${avatar(r.agent)}<div><strong>${agents[r.agent].name}</strong><small>Connected to your space <span>✓</span></small></div></div><div class="detail-tools"><span class="status-badge ${answer?'answered':''}">${answer?'Answered':snoozed?'For later':'Waiting for you'}</span><button class="icon-button" id="snooze" aria-label="${snoozed?'Return to inbox':'Save for later'}" title="${snoozed?'Return to inbox':'Save for later'}" ${answer?'disabled':''}>${icon('clock')}</button><a class="icon-button" href="#connections" aria-label="View agent connection" title="View connection">${icon('connections')}</a></div></header><div class="detail-scroll"><div class="detail-meta"><span>${r.project}</span><span class="separator">/</span><span>${r.label}</span><span style="margin-left:auto">${r.time} ago</span></div><h2 class="detail-title">${r.title}</h2><p class="detail-intro">${r.intro}</p>${requestContent(r)}${comments.length?`<div class="reply-thread">${comments.map(c=>`<div class="sender"><span class="avatar human small">sm</span><div><strong>You</strong><small>Just now</small></div></div><p>${escape(c)}</p>`).join('')}</div>`:''}</div><footer class="detail-footer">${answer?`<div class="response-receipt">${icon('check')} <strong>Your response is with ${agents[r.agent].name}.</strong><p>${escape(answer)}</p></div><div class="action-row"><button class="button secondary" id="reopen">Reopen for exploration</button><span class="privacy-note">Prototype response</span></div>`:`<form id="reply-form">${r.type==='approval'?`<div class="decision-summary approval-context"><p><strong id="hotel-summary">${hotels[hotel].name} · 3 nights</strong>Nov 7–10 · Free cancellation</p><div class="amount" id="hotel-total">${hotels[hotel].total}<small>Total, including taxes</small></div></div>`:''}<label class="reply-label" for="reply">${icon(r.type==='question'?'question':'send')}${r.type==='question'?'Your reply':'Add a thought or ask for a change'}</label><div class="reply-box"><textarea id="reply" rows="1" placeholder="${r.type==='question'?'Something slow, with a little room to breathe…':'A little context, in your own words…'}" aria-label="Reply to ${agents[r.agent].name}"></textarea><button class="reply-send" type="submit" aria-label="Send reply">${icon('arrow')}</button></div><div class="action-row">${r.type==='approval'?`<button class="button primary" type="button" id="primary-action">${icon('check')}Approve booking</button><button class="button secondary" type="button" id="reject-action">Not this one</button>`:r.type==='choice'?`<button class="button primary" type="button" id="primary-action">Confirm choice ${icon('arrow')}</button>`:r.type==='review'?`<button class="button primary" type="button" id="primary-action">${icon('check')}Looks good</button><button class="button secondary" type="button" id="request-changes">Request changes</button>`:`<button class="button primary" type="submit">Send reply ${icon('arrow')}</button>`}<span class="privacy-note">${icon('lock')}Only you & ${agents[r.agent].name}</span></div></form>`}</footer>`;}
function answerRequest(text){state.answers[state.selected]=text;state.snoozed=state.snoozed.filter(id=>id!==state.selected);persist();nav();inbox({keepSelected:true});toast('Response saved. In the live app, your agent would continue.');}
function bindInbox(){document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;state.mobileDetail=false;inbox();});document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.request;state.mobileDetail=true;inbox();});$('#sort').onchange=e=>{state.sort=e.target.value;inbox();};bindDetail();}
function bindDetail(){if(!state.selected)return;const r=requests.find(r=>r.id===state.selected);$('#back-list')?.addEventListener('click',()=>{state.mobileDetail=false;inbox();});$('#snooze')?.addEventListener('click',()=>{const was=state.snoozed.includes(r.id);state.snoozed=was?state.snoozed.filter(id=>id!==r.id):[...state.snoozed,r.id];persist();nav();inbox();toast(was?'Returned to Needs you.':'Saved for later. Your agent can wait.');});$('#reopen')?.addEventListener('click',()=>{delete state.answers[r.id];state.filter='all';persist();nav();inbox();});$('#expand-canvas')?.addEventListener('click',()=>{const dialog=$('#canvas-dialog');dialog.querySelector('iframe').src=`/prototypes/desktop/canvases/trip.html?hotel=${hotel}&theme=${state.theme}`;dialog.showModal();});$('#reply-form')?.addEventListener('submit',e=>{e.preventDefault();const input=$('#reply');const text=input.value.trim();if(!text){input.focus();toast('Add a few words before sending.');return;}if(r.type==='question'){answerRequest(text);return;}state.comments[r.id]=[...(state.comments[r.id]||[]),text];persist();$('#request-detail').innerHTML=detail(r);bindDetail();toast('Your thought is in the conversation. The decision stays open.');});$('#primary-action')?.addEventListener('click',()=>{const comment=$('#reply')?.value.trim();if(r.type==='choice')state.choices[r.id]=$('input[name="architecture"]:checked').value;let text=r.type==='approval'?`Approved ${hotels[hotel].name}, Nov 7–10, for ${hotels[hotel].total} total.`:r.type==='choice'?`Selected: ${$('input[name="architecture"]:checked').value}.`:'Approved the draft.';if(comment)text+=' '+comment;answerRequest(text);});$('#reject-action')?.addEventListener('click',()=>answerRequest('Not this stay. Please find another option.'+($('#reply').value.trim()?' '+$('#reply').value.trim():'')));$('#request-changes')?.addEventListener('click',()=>{const input=$('#reply');if(!input.value.trim()){input.placeholder='What would you like to change?';input.focus();toast('Describe the change, then choose Request changes.');}else answerRequest('Changes requested: '+input.value.trim());});document.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>{$('#reply').value=b.dataset.suggestion;$('#reply').focus();});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const content=b.dataset.download==='onboarding'?'A little room for you.\n\nYour agents can do a lot. Every now and then, they need something only you can give: a decision, a detail, a go-ahead.\n\nThis is where those moments come together. Connect your first agent, and let it meet you here.\n\nYou set the boundaries. They take it from there.':'Agent identity — working notes\n\n1. A handle is an invitation to connect.\n2. Make the scope understandable.\n3. Give trust an expiration.';const url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=b.dataset.download+'-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Saved a copy of the sample draft.');});}
function activity(){const sessions=[['codex','Build the Somae request loop','Somae · Started 24m ago','Needs you','runs'],['roam','A few days in Austin','Personal · Started 18m ago','Needs you','austin'],['research','Map the connection flow','Somae · Started 6m ago','Running',null],['claude','Write the first hello','Somae · Finished 14m ago','Completed','onboarding']];$('#main').innerHTML=heading('Quietly in motion','A window into everything working for you.')+`<div class="content-scroll"><section class="panel"><div class="section-bar"><h2>With you today</h2><span class="eyebrow">4 SESSIONS</span></div>${sessions.map(([a,title,sub,status,id])=>`<div class="session-row">${avatar(a)}<div><h3>${title}</h3><p>${agents[a].name} · ${sub}</p></div><span class="session-status ${status==='Needs you'?'waiting':''}">${status==='Completed'?icon('check'):'<span class="status-dot"></span>'}${status}</span><button class="button secondary" data-session="${id||'timeline'}">${id?'Open':'Follow'} ${icon('arrow')}</button></div>`).join('')}</section><section class="panel" style="margin-top:18px" id="activity-timeline"><h2>The little things, moving forward</h2><div class="timeline"><div class="timeline-item">Roam found three stays that fit your trip.<small>2 minutes ago · Waiting for your approval</small></div><div class="timeline-item">Codex is ready to draft the agent runs migration.<small>8 minutes ago · Waiting for your choice</small></div><div class="timeline-item">Claude Code finished the onboarding copy.<small>14 minutes ago · Draft attached for review</small></div><div class="timeline-item">Fieldwork started mapping the connection flow.<small>6 minutes ago · Reading your working notes</small></div></div></section></div>`;document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>{if(b.dataset.session==='timeline'){$('#activity-timeline').scrollIntoView({behavior:'smooth'});toast('Fieldwork is reading your working notes.');}else{state.selected=b.dataset.session;state.filter=state.answers[state.selected]?'answered':state.snoozed.includes(state.selected)?'later':'all';state.mobileDetail=true;location.hash='inbox';}});}
function connections(){const scopes={codex:['Questions & choices','Approvals','Session activity'],claude:['Questions & choices','Artifact reviews','Session activity'],roam:['Questions','Booking approvals'],research:['Artifact reviews','Read: Somae context']};$('#main').innerHTML=heading('Good company','The agents you’ve invited into your space.')+`<div class="content-scroll"><div class="section-grid">${Object.keys(agents).map(a=>`<section class="panel connection-card"><div class="sender">${avatar(a)}<div><strong>${agents[a].name}</strong><small>${state.connections[a]?'Connected to @'+escape(state.profile.handle):'Connection paused'}</small></div></div><p>${a==='roam'?'A little help with places to go and things to do.':a==='research'?'Thoughtful research, with sources and context.':'Your collaborator for building Somae.'}</p><div class="scope-list">${scopes[a].map(s=>`<span>${s}</span>`).join('')}</div><div class="card-foot"><span>${state.connections[a]?'✓ Until you revoke access':'No active permissions'}</span><button class="button secondary" data-connection="${a}">${state.connections[a]?'Pause access':'Reconnect'}</button></div></section>`).join('')}</div><div class="note-block">You decide who can reach you. Connection changes here are part of the prototype.</div></div>`;document.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>{const a=b.dataset.connection;state.connections[a]=!state.connections[a];persist();connections();toast(`${agents[a].name} ${state.connections[a]?'reconnected':'access paused'} in this prototype.`);});}
function connectionRequests(){const pending=[{id:'studio',name:'Studio',initial:'s',description:'A design companion would like to share work with you.',reason:'“I’m helping with the Somae desktop design. I’d like to send you layouts for review and ask a question when I’m stuck.”',scopes:['Send review requests','Ask questions','Attach design artifacts']},{id:'brian',name:'Brian’s agent',initial:'b',description:'An agent working with @brian would like a moment of your time.',reason:'“Brian would like your thoughts on the shared API contract. This connection is for one question.”',scopes:['Ask one question']}].filter(r=>state.pending[r.id]);$('#main').innerHTML=heading('An invitation to connect','A new face needs your permission before it can reach you.')+`<div class="content-scroll"><div class="section-grid">${pending.map(r=>`<section class="panel"><div class="connection-request-header"><div class="sender"><span class="avatar roam">${r.initial}</span><div><strong>${r.name}</strong><small>New connection</small></div></div><small>Just arrived</small></div><h2>${r.description}</h2><p>${r.reason}</p><div class="permission-list">${r.scopes.map((s,i)=>`<label><input type="checkbox" checked value="${escape(s)}" data-scope="${r.id}">${s}</label>`).join('')}</div><div class="action-row"><button class="button primary" data-allow="${r.id}">Allow once ${icon('check')}</button><button class="button secondary" data-decline="${r.id}">Decline</button></div><p style="font-size:10px;margin:18px 0 0">${icon('lock')} No access to your personal context.</p></section>`).join('')||`<section class="panel empty-state wide">${icon('leaf')}<h2>Your boundaries are in place.</h2><p>No new connection requests.</p><button class="button secondary" id="reset-invitations">Show sample invitations again</button></section>`}</div></div>`;document.querySelectorAll('[data-allow]').forEach(b=>b.onclick=()=>{const id=b.dataset.allow;const checked=[...document.querySelectorAll(`[data-scope="${id}"]:checked`)];if(!checked.length){toast('Choose at least one permission to allow.');return;}state.pending[id]=false;persist();nav();connectionRequests();toast(`One-time connection allowed with ${checked.length} permission${checked.length===1?'':'s'} in this prototype.`);});document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>{state.pending[b.dataset.decline]=false;persist();nav();connectionRequests();toast('Invitation declined.');});$('#reset-invitations')?.addEventListener('click',()=>{state.pending={studio:true,brian:true};persist();nav();connectionRequests();});}
const contexts=[{id:'somae',title:'Somae',description:'The thing we’re building. Decisions, working notes, and a little direction.',count:'6 notes',access:'Shared with 2 agents',text:'Somae is a human control plane for agents.\n\nThe first version proves three loops: MCP request and reply, SDK connection and request, and cross-agent activity.\n\nA handle allows discovery. An explicit scoped grant allows interaction.\n\nDesktop is the power interface. Mobile is the interrupt endpoint.'},{id:'preferences',title:'The way I like things',description:'Preferences that help your agents understand what feels like you.',count:'4 notes',access:'Private to you',text:'Keep things simple and thoughtful.\n\nWarm, human colors. Earth, clay, petal, and leaf.\n\nGive me the context I need to make a decision.\n\nAsk before booking or publishing anything.'},{id:'travel',title:'Out in the world',description:'Places, plans, and the details that make getting away a little easier.',count:'3 notes',access:'Shared with Roam',text:'Austin · November 7–10\n\nPrefer walkable places, thoughtful design, and a little access to nature.\n\nStay budget: under $1,600 for three nights.\n\nFree cancellation matters.'}];
function context(){ $('#main').innerHTML=heading('A little of your world','Context you own. Shared only when you choose.')+`<div class="content-scroll"><div class="context-grid">${contexts.map(c=>`<section class="panel context-card">${icon(c.id==='preferences'?'heart':c.id==='travel'?'globe':'folder')}<h2>${c.title}</h2><p>${c.description}</p><div class="context-foot"><span>${c.count}<br>${c.access}</span><button class="button secondary" data-context="${c.id}">Open ${icon('arrow')}</button></div></section>`).join('')}</div><div class="note-block"><strong>Your context stays yours.</strong> Agent conversations and activity don’t become memory automatically. You choose what belongs here.</div></div>`;document.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>openContext(b.dataset.context)); }
function openContext(id){const c=contexts.find(c=>c.id===id);$('#main').innerHTML=heading(c.title,c.access,'YOUR CONTEXT')+`<div class="content-scroll"><section class="panel"><a class="button subtle" href="#context" id="back-context">${icon('back')}All collections</a><p style="margin-top:20px">${c.description}</p><label class="eyebrow" for="context-editor">YOUR WORKING NOTES</label><textarea class="context-editor" id="context-editor">${escape(state.context[id]||c.text)}</textarea><div class="action-row"><button class="button primary" id="save-context">Save notes ${icon('check')}</button><span class="privacy-note">Saved only in this browser</span></div></section></div>`;$('#back-context').onclick=e=>{e.preventDefault();context();};$('#save-context').onclick=()=>{state.context[id]=$('#context-editor').value;persist();toast('Your notes are saved in this prototype.');};}
function appearance(){ $('#main').innerHTML=heading('Make yourself at home','Three ways to feel a little more human.','MAKE IT YOURS')+`<div class="content-scroll"><div class="theme-grid">${[['clay','Clay','Terracotta, cream, and a little warmth.'],['petal','Petal','Soft rose, peach, and warm linen.'],['meadow','Meadow','Olive, oat, and the feeling of outside.']].map(([id,title,desc])=>`<button class="theme-card ${state.theme===id?'active':''}" data-theme-choice="${id}" aria-pressed="${state.theme===id}"><div class="theme-preview" data-theme="${id}"><div class="mini-nav"><i></i><i></i><i></i></div><div class="mini-workspace"><b></b><div class="mini-panes"><i></i><i></i></div></div></div><h3>${title} ${state.theme===id?'✓':''}</h3><p>${desc}</p></button>`).join('')}</div><section class="panel"><span class="eyebrow">A SHARED PALETTE</span><h2>Color with a little life in it.</h2><p>Earth for grounding. Petal for warmth. Leaf for things moving forward.<br>Every surface, line, and word belongs to the same palette.</p><div class="swatches">${['canvas','surface','accent-soft','accent','petal','leaf-soft','leaf','ink'].map(s=>`<span class="swatch" style="--swatch:var(--${s})" title="${s}" aria-label="${s} color"></span>`).join('')}</div><div class="token-description"><div><strong>Soft, distinct surfaces</strong>Space between your world and an agent’s canvas.</div><div><strong>A human voice</strong>Lora for presence. DM Sans for clarity.</div><div><strong>Room to breathe</strong>Generous spacing. Gentle, consistent curves.</div></div></section><div class="action-row"><button class="button secondary" id="reset-prototype">Reset sample data</button><span style="font-size:10px;color:var(--ink-muted)">Responses and preferences live in this browser.</span></div></div>`;document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.themeChoice;document.documentElement.dataset.theme=state.theme;persist();appearance();});$('#reset-prototype').onclick=()=>{state.answers={};state.choices={};state.comments={};state.snoozed=[];state.pending={studio:true,brian:true};state.connections={codex:true,claude:true,roam:true,research:true};state.context={};state.selected='austin';state.filter='all';persist();nav();toast('Sample requests and connections restored.');}; }
function profile(){ $('#main').innerHTML=heading('Your little corner','A name, a handle, and a way to find you.')+`<div class="content-scroll"><section class="panel profile-panel"><div class="profile-heading"><span class="avatar human">sm</span><div><h2>${escape(state.profile.name)}</h2><p>@${escape(state.profile.handle)}</p></div></div><p>Your handle is an invitation to connect. You still decide who gets to reach you.</p><form id="profile-form"><div class="profile-fields"><div class="field"><label for="profile-name">Your name</label><input id="profile-name" value="${escape(state.profile.name)}" required maxlength="80"></div><div class="field"><label for="profile-handle">Handle</label><input id="profile-handle" value="${escape(state.profile.handle)}" required pattern="[a-zA-Z0-9_]{2,30}" title="2–30 letters, numbers, or underscores"></div><div class="field wide"><label for="profile-bio">A little about you</label><input id="profile-bio" value="${escape(state.profile.bio)}" maxlength="200"></div></div><button class="button primary" type="submit">Save profile ${icon('check')}</button></form></section></div>`;$('#profile-form').onsubmit=e=>{e.preventDefault();state.profile={name:$('#profile-name').value.trim(),handle:$('#profile-handle').value.trim(),bio:$('#profile-bio').value.trim()};persist();document.querySelector('.profile-link strong').textContent=state.profile.name;document.querySelector('.profile-link small').textContent='@'+state.profile.handle;profile();toast('Profile saved in this prototype.');}; }
function route(){ const hash=location.hash.slice(1)||'inbox';activePage=['inbox','activity','requests','context','connections','appearance','profile'].includes(hash)?hash:'inbox';const labels={inbox:'Needs you',activity:'Activity',requests:'Requests',context:'Context',connections:'Connections',appearance:'Appearance',profile:'Profile'};$('#breadcrumb-current').textContent=labels[activePage];nav();({inbox,activity,requests:connectionRequests,context,connections,appearance,profile})[activePage](); }
function searchResults(){const q=$('#global-search').value.trim().toLowerCase();const matches=requests.filter(r=>[r.title,r.preview,r.project,agents[r.agent].name].some(s=>s.toLowerCase().includes(q)));$('#search-results').innerHTML=matches.map(r=>`<button class="search-result" data-search-request="${r.id}">${avatar(r.agent)}<span><strong>${r.title}</strong><small>${agents[r.agent].name} · ${r.project}${state.answers[r.id]?' · Answered':''}</small></span></button>`).join('')||'<p style="padding:12px;font-size:12px">Nothing here yet. Try an agent name or project.</p>';document.querySelectorAll('[data-search-request]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.searchRequest;state.filter=state.answers[state.selected]?'answered':state.snoozed.includes(state.selected)?'later':'all';state.mobileDetail=true;$('#search-dialog').close();if(location.hash==='#inbox'||!location.hash)route();else location.hash='inbox';});}
function openSearch(){ $('#search-dialog').showModal();$('#global-search').value='';searchResults();$('#global-search').focus(); }
$('#search-icon').innerHTML=icon('search');$('#quiet-button').innerHTML=icon(state.quiet?'quiet':'bell');$('#quiet-button').setAttribute('aria-pressed',state.quiet);$('#search-trigger').onclick=openSearch;$('#global-search').oninput=searchResults;$('#quiet-button').onclick=()=>{state.quiet=!state.quiet;persist();$('#quiet-button').innerHTML=icon(state.quiet?'quiet':'bell');$('#quiet-button').setAttribute('aria-pressed',state.quiet);$('#quiet-button').setAttribute('aria-label',state.quiet?'Resume notifications':'Pause notifications');toast(state.quiet?'A quiet moment. Notifications paused in this prototype.':'Notifications resumed in this prototype.');};
$('#close-canvas').onclick=()=>$('#canvas-dialog').close();$('#canvas-return').onclick=()=>{$('#canvas-dialog').close();$('#reply')?.focus();};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search-dialog').open)openSearch();}});
window.addEventListener('message',e=>{const frames=[$('#trip-canvas'),$('#canvas-dialog iframe')].filter(Boolean);if(!frames.some(frame=>frame.contentWindow===e.source)||e.data?.type!=='hotel-select'||!hotels[e.data.hotel])return;hotel=e.data.hotel;if($('#hotel-summary')){$('#hotel-summary').textContent=hotels[hotel].name+' · 3 nights';$('#hotel-total').innerHTML=hotels[hotel].total+'<small>Total, including taxes</small>';}for(const frame of frames)if(frame.contentWindow!==e.source)frame.contentWindow.postMessage({type:'hotel-sync',hotel},'*');});
window.addEventListener('hashchange',route);document.documentElement.dataset.theme=['clay','petal','meadow'].includes(state.theme)?state.theme:'clay';document.querySelector('.profile-link strong').textContent=state.profile.name;document.querySelector('.profile-link small').textContent='@'+state.profile.handle;route();
